import numpy as np

def matrix_mult(A, B):
    return np.dot(A, B)

def matrix_pow(A, n):
    if n == 0:
        return np.identity(A.shape[0], dtype=int)
    if n == 1:
        return A
    if n % 2 == 0:
        half = matrix_pow(A, n // 2)
        return matrix_mult(half, half)
    else:
        return matrix_mult(A, matrix_pow(A, n - 1))

M = np.array([
    [1, 1, 1],
    [1, 0, 1],
    [1, 1, 0]
], dtype=np.int64)

D1 = np.array([1, 1, 1], dtype=np.int64)

# Calculate M^20
M_20 = matrix_pow(M, 20)

# Calculate D21 = M^20 * D1
D21 = np.dot(M_20, D1)

# Sum the components
total_ways = np.sum(D21)

print(f"M^20:\n{M_20}")
print(f"D21:\n{D21}")
print(f"Total Ways: {total_ways}")
